def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    n_len = len(s)

    # Maximum possible popcount is the length of the string (up to 800)
    MAX_VAL = 800
    steps = [0] * (MAX_VAL + 1)

    def get_popcount(v):
        c = 0
        while v > 0:
            c += (v & 1)
            v >>= 1
        return c

    # Precompute steps for numbers up to MAX_VAL
    # steps[v] is the minimum operations to reduce v to 1
    # Operation: replace x with count of set bits in binary representation
    for v in range(1, MAX_VAL + 1):
        if v == 1:
            steps[v] = 0
        else:
            steps[v] = 1 + steps[get_popcount(v)]

    # Determine valid popcounts: v is valid if it reduces to 1 in <= k-1 steps
    # Because the first operation on x gives popcount(x), and we have k-1 operations left.
    valid_popcounts = set()
    for v in range(1, MAX_VAL + 1):
        if steps[v] <= k - 1:
            valid_popcounts.add(v)

    memo = {}

    def dp(idx, current_pop, tight, started):
        if idx == n_len:
            # We want strictly less than n.
            # If tight is True, it means we formed the number equal to n, so exclude it.
            # If started is False, it means the number is 0, exclude it.
            if started and not tight and current_pop in valid_popcounts:
                return 1
            return 0

        state = (idx, current_pop, tight, started)
        if state in memo:
            return memo[state]

        limit = int(s[idx]) if tight else 1

        res = 0
        for digit in range(0, limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit == 1)
            new_pop = current_pop + (1 if digit == 1 else 0)

            term = dp(idx + 1, new_pop, new_tight, new_started)
            res = (res + term) % MOD

        memo[state] = res
        return res

    return dp(0, 0, True, False)

