from typing import List

def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    # Winning lines: rows, columns, diagonals
    WIN_LINES = [
        [(0,0), (0,1), (0,2)],
        [(1,0), (1,1), (1,2)],
        [(2,0), (2,1), (2,2)],
        [(0,0), (1,0), (2,0)],
        [(0,1), (1,1), (2,1)],
        [(0,2), (1,2), (2,2)],
        [(0,0), (1,1), (2,2)],
        [(0,2), (1,1), (2,0)]
    ]

    def check_win(board: List[List[int]], player: int) -> bool:
        for line in WIN_LINES:
            if all(board[r][c] == player for r, c in line):
                return True
        return False

    def solve(board: List[List[int]], takahashi_score: int, aoki_score: int, is_takahashi_turn: bool, alpha: float, beta: float) -> int:
        # Check if Takahashi has won
        if check_win(board, 1):
            return takahashi_score - aoki_score
        # Check if Aoki has won
        if check_win(board, -1):
            return takahashi_score - aoki_score

        # Check if board is full (all cells painted)
        if not any(cell == 0 for row in board for cell in row):
            return takahashi_score - aoki_score

        # Find all available moves (empty cells)
        moves = []
        for r in range(3):
            for c in range(3):
                if board[r][c] == 0:
                    moves.append((r, c))

        if is_takahashi_turn:
            best_score = float('-inf')
            for r, c in moves:
                # Takahashi takes the cell
                new_board = [row[:] for row in board]
                new_board[r][c] = 1
                new_score = solve(new_board, takahashi_score + grid[r][c], aoki_score, False, alpha, beta)
                best_score = max(best_score, new_score)
                alpha = max(alpha, best_score)
                if beta <= alpha:
                    break
            return best_score
        else:
            best_score = float('inf')
            for r, c in moves:
                # Aoki takes the cell
                new_board = [row[:] for row in board]
                new_board[r][c] = -1
                new_score = solve(new_board, takahashi_score, aoki_score + grid[r][c], True, alpha, beta)
                best_score = min(best_score, new_score)
                beta = min(beta, best_score)
                if beta <= alpha:
                    break
            return best_score

    result = solve(grid, 0, 0, True, float('-inf'), float('inf'))
    return "Takahashi" if result > 0 else "Aoki"

from typing import List
from collections import deque

def min_knight_moves(start_x, start_y, end_x, end_y):
    if start_x == end_x and start_y == end_y:
        return 0

    board_size = 50
    directions = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2)
    ]

    visited = [[False] * board_size for _ in range(board_size)]
    queue = deque()
    queue.append((start_x, start_y, 0))
    visited[start_x][start_y] = True

    while queue:
        x, y, dist = queue.popleft()

        if x == end_x and y == end_y:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < board_size and 0 <= ny < board_size and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny, dist + 1))

    return -1  # Should not happen on a connected board

def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    n = len(positions)
    memo = {}

    def solve(kx, ky, mask):
        if mask == 0:
            return 0

        state = (kx, ky, mask)
        if state in memo:
            return memo[state]

        # Count number of set bits to determine whose turn it is
        # Alice moves when remaining pawns count is odd (since she starts first)
        # But actually, the number of moves made so far is (n - popcount(mask))
        # If moves made so far is even, it's Alice's turn (0, 2, 4...)
        # If moves made so far is odd, it's Bob's turn (1, 3, 5...)
        moves_made = n - bin(mask).count('1')
        is_alice_turn = (moves_made % 2 == 0)

        best = float('-inf') if is_alice_turn else float('inf')

        for i in range(n):
            if mask & (1 << i):
                px, py = positions[i]
                moves_needed = min_knight_moves(kx, ky, px, py)
                new_mask = mask ^ (1 << i)
                rest = solve(px, py, new_mask)
                total = moves_needed + rest

                if is_alice_turn:
                    if total > best:
                        best = total
                else:
                    if total < best:
                        best = total

        memo[state] = best
        return best

    initial_mask = (1 << n) - 1
    return solve(kx, ky, initial_mask)

