def count_good_strings(n: int, k: int, s: str) -> int:
    MOD = 998244353

    if k > n:
        q_count = s.count('?')
        return pow(2, q_count, MOD)

    if k == 1:
        return 0

    mask_len = k - 1
    num_states = 1 << mask_len
    full_mask = (1 << mask_len) - 1

    dp = [0] * num_states
    dp[0] = 1

    # Initialize for the first k-1 characters
    for i in range(0, k-1):
        new_dp = [0] * num_states
        for mask in range(num_states):
            if dp[mask] == 0:
                continue
            if s[i] == '?':
                chars = [0, 1]
            else:
                chars = [0 if s[i] == 'A' else 1]
            for char_val in chars:
                new_mask = ((mask << 1) | char_val) & full_mask
                new_dp[new_mask] = (new_dp[new_mask] + dp[mask]) % MOD
        dp = new_dp

    # Process from k-1 to n-1
    for i in range(k-1, n):
        new_dp = [0] * num_states
        for mask in range(num_states):
            if dp[mask] == 0:
                continue
            if s[i] == '?':
                chars = [0, 1]
            else:
                chars = [0 if s[i] == 'A' else 1]
            for char_val in chars:
                # Check if the substring of length k ending at i is a palindrome
                # The substring consists of the k-1 characters in 'mask' and the current 'char_val'
                # The mask has: bit (k-2) = char at i-k+1, ..., bit 0 = char at i-1
                # The current char_val is at i
                is_palindrome = True
                for j in range(k // 2):
                    # Left character index in the substring: j
                    # Right character index in the substring: k-1-j
                    if j == 0:
                        left_char = (mask >> (k - 2)) & 1
                        right_char = char_val
                    else:
                        left_char = (mask >> (k - 2 - j)) & 1
                        # Right character is at index k-1-j in the substring, which corresponds to bit (k-2 - (k-1-j)) = j-1 in the mask
                        right_char = (mask >> (j - 1)) & 1

                    if left_char != right_char:
                        is_palindrome = False
                        break

                if is_palindrome:
                    continue

                new_mask = ((mask << 1) | char_val) & full_mask
                new_dp[new_mask] = (new_dp[new_mask] + dp[mask]) % MOD
        dp = new_dp

    return sum(dp) % MOD

